"use client";

import * as React from "react";

import { useControllableState } from "@/hooks/use-controllable-state";
import { DEFAULT_WORKING_HOURS } from "@/lib/free-busy";
import {
  addEmail,
  getCalendarPerson,
  isSameEmail,
  removeEmail,
} from "@/lib/people";
import type {
  CalendarPeopleValue,
  DetailedCalendarEvent,
  EventContact,
  WorkingHours,
} from "@/components/calendar-types";

/** Nobody met with or shown when no list is given (stable identity) */
const NO_EMAILS: string[] = [];

/** No events for anyone when `contactEvents` is not set (stable identity) */
const NO_CONTACT_EVENTS: Record<string, DetailedCalendarEvent[]> = {};

/** A person without events in `contactEvents` (stable identity) */
const NO_PERSON_EVENTS: DetailedCalendarEvent[] = [];

/** Outside a provider: nobody shows, and nobody can be added */
const NO_PEOPLE: CalendarPeopleValue = {
  contacts: [],
  meetWith: NO_EMAILS,
  teammates: NO_EMAILS,
  shownPeople: [],
  addMeetWith: () => {},
  removeMeetWith: () => {},
  clearMeetWith: () => {},
  addTeammate: () => {},
  removeTeammate: () => {},
  getPersonEvents: () => NO_PERSON_EVENTS,
  workingHours: DEFAULT_WORKING_HOURS,
};

const CalendarPeopleContext =
  React.createContext<CalendarPeopleValue>(NO_PEOPLE);

/** What `useCalendarPeopleState` reads: the provider's people props */
interface CalendarPeopleStateOptions {
  contacts: EventContact[];
  meetWith?: string[];
  defaultMeetWith?: string[];
  onMeetWithChange?: (meetWith: string[]) => void;
  teammates?: string[];
  defaultTeammates?: string[];
  onTeammatesChange?: (teammates: string[]) => void;
  contactEvents?: Record<string, DetailedCalendarEvent[]>;
  workingHours?: WorkingHours;
}

/**
 * The people state behind `useCalendarPeople()`, owned by
 * `CalendarProvider`: who you meet with and which teammates show, each list
 * controlled or not, and their events from `contactEvents`.
 */
export function useCalendarPeopleState({
  contacts,
  meetWith: meetWithProp,
  defaultMeetWith = NO_EMAILS,
  onMeetWithChange,
  teammates: teammatesProp,
  defaultTeammates = NO_EMAILS,
  onTeammatesChange,
  contactEvents = NO_CONTACT_EVENTS,
  workingHours = DEFAULT_WORKING_HOURS,
}: CalendarPeopleStateOptions): CalendarPeopleValue {
  const [meetWith, setMeetWith] = useControllableState({
    prop: meetWithProp,
    defaultProp: defaultMeetWith,
    onChange: onMeetWithChange,
  });
  const [teammates, setTeammates] = useControllableState({
    prop: teammatesProp,
    defaultProp: defaultTeammates,
    onChange: onTeammatesChange,
  });

  const addMeetWith = React.useCallback(
    (email: string) =>
      setMeetWith((prev) =>
        prev.some((e) => isSameEmail(e, email)) ? prev : addEmail(prev, email),
      ),
    [setMeetWith],
  );

  const removeMeetWith = React.useCallback(
    (email: string) =>
      setMeetWith((prev) =>
        prev.some((e) => isSameEmail(e, email))
          ? removeEmail(prev, email)
          : prev,
      ),
    [setMeetWith],
  );

  const clearMeetWith = React.useCallback(
    () => setMeetWith((prev) => (prev.length === 0 ? prev : NO_EMAILS)),
    [setMeetWith],
  );

  const addTeammate = React.useCallback(
    (email: string) =>
      setTeammates((prev) =>
        prev.some((e) => isSameEmail(e, email)) ? prev : addEmail(prev, email),
      ),
    [setTeammates],
  );

  const removeTeammate = React.useCallback(
    (email: string) =>
      setTeammates((prev) =>
        prev.some((e) => isSameEmail(e, email))
          ? removeEmail(prev, email)
          : prev,
      ),
    [setTeammates],
  );

  // Looked up without case: apps key `contactEvents` as their API spells
  // the address
  const eventsByEmail = React.useMemo(() => {
    const map = new Map<string, DetailedCalendarEvent[]>();
    for (const [email, events] of Object.entries(contactEvents)) {
      map.set(email.trim().toLowerCase(), events);
    }
    return map;
  }, [contactEvents]);

  const getPersonEvents = React.useCallback(
    (email: string) =>
      eventsByEmail.get(email.trim().toLowerCase()) ?? NO_PERSON_EVENTS,
    [eventsByEmail],
  );

  const shownPeople = React.useMemo(
    () =>
      [
        ...meetWith,
        ...teammates.filter((t) => !meetWith.some((m) => isSameEmail(m, t))),
      ].map((email) => getCalendarPerson(contacts, email)),
    [contacts, meetWith, teammates],
  );

  return React.useMemo(
    () => ({
      contacts,
      meetWith,
      teammates,
      shownPeople,
      addMeetWith,
      removeMeetWith,
      clearMeetWith,
      addTeammate,
      removeTeammate,
      getPersonEvents,
      workingHours,
    }),
    [
      contacts,
      meetWith,
      teammates,
      shownPeople,
      addMeetWith,
      removeMeetWith,
      clearMeetWith,
      addTeammate,
      removeTeammate,
      getPersonEvents,
      workingHours,
    ],
  );
}

/** Props of `CalendarPeopleProvider` */
interface CalendarPeopleProviderProps {
  /** The state from `useCalendarPeopleState` */
  value: CalendarPeopleValue;
  children?: React.ReactNode;
}

/** Hands the provider's people state to `useCalendarPeople()` */
export function CalendarPeopleProvider({
  value,
  children,
}: CalendarPeopleProviderProps) {
  return (
    <CalendarPeopleContext.Provider value={value}>
      {children}
    </CalendarPeopleContext.Provider>
  );
}

/**
 * The people whose calendars show beside yours, from the nearest
 * `CalendarProvider`: who you meet with ("Meet with..."), the teammates
 * shown ("Show teammate calendar..."), their events and the actions that
 * add and remove them. Outside a provider, nobody shows.
 */
export function useCalendarPeople(): CalendarPeopleValue {
  return React.useContext(CalendarPeopleContext);
}

import * as React from "react";

import {
  useCalendar,
  useCalendarEventActions,
} from "@/components/calendar-provider";
import type { CalendarContextValue } from "@/components/calendar-types";

interface UseCalendarShortcutsOptions {
  /** Whether the shortcuts are active. Defaults to true */
  enabled?: boolean;
  /** Cmd+K / Ctrl+K, even from inside a text field: opens or closes a command menu */
  onToggleCommandMenu?: () => void;
  /** Cmd+/ (the Meta key, also on Windows and Linux): opens or closes the sidebar */
  onToggleSidebar?: () => void;
  /** /: opens or closes the context panel */
  onToggleContextPanel?: () => void;
  /** Shift+M: switches to the next theme */
  onCycleTheme?: () => void;
  /** Cmd+, / Ctrl+,, even from inside a text field: opens the settings */
  onOpenSettings?: () => void;
  /** .: opens Go to date (the demo's command menu, on its date field) */
  onGoToDate?: () => void;
  /** ?: shows the full keyboard shortcut list */
  onShowShortcuts?: () => void;
  /** Z: opens a picker to travel to a time zone ("Travel to time zone...") */
  onTravelToTimeZone?: () => void;
  /** F: opens "Meet with..." */
  onMeetWith?: () => void;
  /** P: opens "Show teammate calendar..." */
  onShowTeammateCalendar?: () => void;
}

/** App actions some keys trigger. A key is claimed only when its action is given */
type AppShortcutActions = Omit<UseCalendarShortcutsOptions, "enabled">;

/** Calendar actions the shortcuts trigger */
type CalendarShortcutActions = Pick<
  CalendarContextValue,
  | "goToToday"
  | "goToPrev"
  | "goToNext"
  | "switchView"
  | "setNumberOfDays"
  | "clearSelection"
  | "toggleWeekends"
  | "zoomHoursIn"
  | "zoomHoursOut"
  | "resetHourHeight"
  | "addEventAtNextSlot"
  | "travelTimeZone"
  | "travelToTimeZone"
>;

/** Event actions the event keys run, and what says whether each has something to act on */
type EditShortcutActions = Pick<
  CalendarContextValue,
  | "deleteEvent"
  | "duplicateEvent"
  | "copyEvent"
  | "cutEvent"
  | "pasteEvent"
  | "undo"
  | "redo"
  | "canUndo"
  | "canRedo"
> & {
  /** The selected event's id, or `null` when none (or a missing one) is selected */
  selectedEventId: string | null;
  /** Whether a cut or copied event waits to be pasted */
  hasCopiedEvent: boolean;
};

/** Everything the window listener reads */
type ShortcutActions = CalendarShortcutActions &
  EditShortcutActions &
  AppShortcutActions;

/** Keys 2-9: show that many days */
const NUMBER_OF_DAYS_KEY = /^[2-9]$/;

/**
 * Shift+Cmd with these keys zooms the hours, by `KeyboardEvent.code`: Shift
 * turns their `key` into ">", "<" and ")" on most layouts
 */
const HOUR_ZOOM_CODES = {
  in: "Period",
  out: "Comma",
  reset: "Digit0",
} as const;

/** Tags of the form fields that take key presses themselves */
const TYPING_TAGS = new Set(["INPUT", "TEXTAREA", "SELECT"]);

/** Dialogs, menus and lists whose own Escape closes them */
const ESCAPE_LAYER_SELECTOR =
  '[role="dialog"], [role="menu"], [role="listbox"], [data-slot="popover-content"]';

/** Whether a key press is typed into a field: an input, a textarea, a select or editable content (single-key shortcuts skip those) */
export function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return TYPING_TAGS.has(target.tagName) || target.isContentEditable;
}

/** Whether a key press is part of an IME composition (Safari reports keyCode 229 with `isComposing` already false) */
function isComposingKey(e: KeyboardEvent): boolean {
  return e.isComposing || e.keyCode === 229;
}

/** Whether text is selected on the page, which Cmd+C and Cmd+X then copy or cut instead */
function hasTextSelection(): boolean {
  const selection = window.getSelection();
  return selection !== null && !selection.isCollapsed;
}

/**
 * Handles the keys that change events: Delete and Backspace, Cmd+X, Cmd+C
 * and Cmd+D on the selected event, Cmd+V, Cmd+Z and Shift+Cmd+Z (Ctrl on
 * Windows and Linux). Returns whether one ran. A key with nothing to act on
 * (no selected event, nothing to paste, undo or redo) is left to the
 * browser, and so is every key typed into a field, during an IME
 * composition, with Alt, or (Cmd+C, Cmd+X) with text selected on the page.
 */
function handleEditShortcut(
  e: KeyboardEvent,
  actions: EditShortcutActions,
): boolean {
  if (e.altKey || isComposingKey(e) || isTypingTarget(e.target)) return false;
  const run = (action: () => void) => {
    e.preventDefault();
    action();
    return true;
  };
  const isCommand = e.metaKey || e.ctrlKey;
  const key = e.key.toLowerCase();
  const { selectedEventId } = actions;

  if (isCommand && key === "z") {
    if (e.shiftKey) return actions.canRedo && run(actions.redo);
    return actions.canUndo && run(actions.undo);
  }
  if (isCommand && !e.shiftKey && key === "v") {
    return actions.hasCopiedEvent && run(actions.pasteEvent);
  }
  if (!selectedEventId) return false;
  if (!isCommand && (e.key === "Delete" || e.key === "Backspace")) {
    return run(() => actions.deleteEvent(selectedEventId));
  }
  if (!isCommand || e.shiftKey) return false;
  if (key === "d") return run(() => actions.duplicateEvent(selectedEventId));
  // With text selected, Cmd+C and Cmd+X copy or cut the text
  if (hasTextSelection()) return false;
  if (key === "c") return run(() => actions.copyEvent(selectedEventId));
  if (key === "x") return run(() => actions.cutEvent(selectedEventId));
  return false;
}

/**
 * Handles the app's keys, before the calendar's. Returns whether one ran. One
 * that runs stops the event, so no later `keydown` listener also acts on it
 * (e.g. Shift+M, next to the calendar's M).
 */
function handleAppShortcut(
  e: KeyboardEvent,
  actions: AppShortcutActions,
): boolean {
  const run = (action: (() => void) | undefined) => {
    if (!action) return false;
    e.preventDefault();
    e.stopImmediatePropagation();
    action();
    return true;
  };
  const isCommand = e.metaKey || e.ctrlKey;

  if (isCommand && e.key === "k") return run(actions.onToggleCommandMenu);
  if (e.metaKey && e.key === "/") return run(actions.onToggleSidebar);
  if (isCommand && !e.shiftKey && e.key === ",") {
    return run(actions.onOpenSettings);
  }

  // Single keys only from here: they'd be typed into a text field
  if (isTypingTarget(e.target)) return false;

  if (e.key === "/" && !isCommand && !e.altKey) {
    return run(actions.onToggleContextPanel);
  }
  if (e.key === "M" && e.shiftKey && !isCommand) {
    return run(actions.onCycleTheme);
  }
  if (isCommand || e.altKey) return false;
  if (e.key === ".") return run(actions.onGoToDate);
  if (e.key === "?") return run(actions.onShowShortcuts);
  if (e.key === "z" || e.key === "Z") return run(actions.onTravelToTimeZone);
  if (e.key === "f" || e.key === "F") return run(actions.onMeetWith);
  if (e.key === "p" || e.key === "P") {
    return run(actions.onShowTeammateCalendar);
  }
  return false;
}

/**
 * Handles one key press. Returns early on the first match, in the same
 * order the demo has always checked them.
 */
function handleShortcut(
  e: KeyboardEvent,
  actions: CalendarShortcutActions &
    Pick<EditShortcutActions, "selectedEventId">,
): void {
  // Escape deselects, even from inside a text field. With nothing selected
  // it travels back home, as in Notion Calendar, unless it closes a layer
  if (e.key === "Escape") {
    const closesLayer =
      e.target instanceof Element &&
      e.target.closest(ESCAPE_LAYER_SELECTOR) !== null;
    if (!actions.selectedEventId && actions.travelTimeZone && !closesLayer) {
      actions.travelToTimeZone(null);
      return;
    }
    actions.clearSelection();
    return;
  }

  const isCommand = e.metaKey || e.ctrlKey;
  const key = e.key.toLowerCase();

  // Shift+Cmd+E (Ctrl on Windows and Linux) toggles weekends, even from
  // inside a text field
  if (isCommand && e.shiftKey && key === "e") {
    e.preventDefault();
    actions.toggleWeekends();
    return;
  }

  // Shift+Cmd+. / , / 0: taller hours, shorter hours, the default height
  if (isCommand && e.shiftKey && !e.altKey) {
    const zoom = {
      [HOUR_ZOOM_CODES.in]: actions.zoomHoursIn,
      [HOUR_ZOOM_CODES.out]: actions.zoomHoursOut,
      [HOUR_ZOOM_CODES.reset]: actions.resetHourHeight,
    }[e.code];
    if (zoom) {
      e.preventDefault();
      zoom();
      return;
    }
  }

  // Single keys only: Cmd+K, Ctrl+D, Alt+ArrowLeft and the like belong to the
  // app and browser
  if (isCommand || e.altKey || isTypingTarget(e.target)) return;

  if (e.key === "t" || e.key === "T") {
    e.preventDefault();
    actions.goToToday();
    return;
  }

  if (e.key === "1" || e.key === "d" || e.key === "D") {
    e.preventDefault();
    actions.switchView("day");
    return;
  }

  if (e.key === "0" || e.key === "w" || e.key === "W") {
    e.preventDefault();
    actions.switchView("week");
    return;
  }

  if (NUMBER_OF_DAYS_KEY.test(e.key)) {
    e.preventDefault();
    actions.setNumberOfDays(Number(e.key));
    return;
  }

  if (e.key === "j" || e.key === "J" || e.key === "ArrowLeft") {
    e.preventDefault();
    actions.goToPrev();
    return;
  }

  if (e.key === "k" || e.key === "K" || e.key === "ArrowRight") {
    e.preventDefault();
    actions.goToNext();
    return;
  }

  // Lowercase only: Shift+M is left free for app shortcuts
  if (e.key === "m") {
    e.preventDefault();
    actions.switchView("month");
    return;
  }

  if (e.key === "y" || e.key === "Y") {
    e.preventDefault();
    actions.switchView("year");
    return;
  }

  if (e.key === "c" || e.key === "C") {
    e.preventDefault();
    actions.addEventAtNextSlot();
    return;
  }

  // Cmd+A / Ctrl+A never get here, so they still select all
  if (e.key === "a" || e.key === "A") {
    e.preventDefault();
    actions.switchView("agenda");
  }
}

/**
 * Opt-in single-key calendar shortcuts, listening on `window`:
 *
 * - T: today
 * - J / ArrowLeft, K / ArrowRight: previous / next period
 * - D or 1: day view, W or 0: week view, M: month view, Y: year view, A: agenda
 * - 2-9: number of days
 * - C: create an event at the next half hour (`addEventAtNextSlot`)
 * - Escape: clear the selection, or with nothing selected travel back home
 * - Delete / Backspace: delete the selected event
 * - Cmd+X, Cmd+C, Cmd+D: cut, copy, duplicate the selected event; Cmd+V:
 *   paste it at the slot under the mouse (Ctrl on Windows and Linux)
 * - Cmd+Z / Shift+Cmd+Z: undo / redo
 * - Shift+Cmd+E (Ctrl on Windows and Linux): show or hide weekends
 * - Shift+Cmd+. / Shift+Cmd+, / Shift+Cmd+0: zoom the hours in, out, or back
 *   to the default height
 *
 * Other presses with Cmd, Ctrl or Alt are left alone, and an event key with
 * nothing to act on is too.
 *
 * The live demo's app keys come on with their actions: Cmd+K
 * (`onToggleCommandMenu`), Cmd+/ (`onToggleSidebar`), / (`onToggleContextPanel`),
 * Shift+M (`onCycleTheme`), Cmd+, (`onOpenSettings`), . (`onGoToDate`), ?
 * (`onShowShortcuts`), Z (`onTravelToTimeZone`), F (`onMeetWith`) and P
 * (`onShowTeammateCalendar`). They're checked first, and one that runs stops
 * the event from reaching later listeners.
 *
 * Key presses in inputs, textareas, selects and editable content are ignored
 * (except Escape, Cmd+K and Cmd+,), and the event keys also during an IME
 * composition. The listener is added once on mount, so
 * its position among other `window` keydown listeners stays fixed: any other
 * app shortcut that shares a key should be handled by a listener added before
 * this hook's, and call `event.stopImmediatePropagation()`.
 */
export function useCalendarShortcuts({
  enabled = true,
  onToggleCommandMenu,
  onToggleSidebar,
  onToggleContextPanel,
  onCycleTheme,
  onOpenSettings,
  onGoToDate,
  onShowShortcuts,
  onTravelToTimeZone,
  onMeetWith,
  onShowTeammateCalendar,
}: UseCalendarShortcutsOptions = {}) {
  const {
    goToToday,
    goToPrev,
    goToNext,
    switchView,
    setNumberOfDays,
    clearSelection,
    toggleWeekends,
    zoomHoursIn,
    zoomHoursOut,
    resetHourHeight,
    addEventAtNextSlot,
    selectedEvent,
    deleteEvent,
    duplicateEvent,
    copyEvent,
    cutEvent,
    pasteEvent,
    undo,
    redo,
    canUndo,
    canRedo,
    travelTimeZone,
    travelToTimeZone,
  } = useCalendar();
  const eventActions = useCalendarEventActions();
  const selectedEventId = selectedEvent?.id ?? null;
  const hasCopiedEvent = eventActions?.hasCopiedEvent ?? false;

  /** Latest actions, read by the window listener */
  const actionsRef = React.useRef<ShortcutActions>({
    goToToday,
    goToPrev,
    goToNext,
    switchView,
    setNumberOfDays,
    clearSelection,
    toggleWeekends,
    zoomHoursIn,
    zoomHoursOut,
    resetHourHeight,
    addEventAtNextSlot,
    selectedEventId,
    hasCopiedEvent,
    deleteEvent,
    duplicateEvent,
    copyEvent,
    cutEvent,
    pasteEvent,
    undo,
    redo,
    canUndo,
    canRedo,
    onToggleCommandMenu,
    onToggleSidebar,
    onToggleContextPanel,
    onCycleTheme,
    onOpenSettings,
    onGoToDate,
    onShowShortcuts,
    onTravelToTimeZone,
    travelTimeZone,
    travelToTimeZone,
    onMeetWith,
    onShowTeammateCalendar,
  });

  React.useEffect(() => {
    actionsRef.current = {
      goToToday,
      goToPrev,
      goToNext,
      switchView,
      setNumberOfDays,
      clearSelection,
      toggleWeekends,
      zoomHoursIn,
      zoomHoursOut,
      resetHourHeight,
      addEventAtNextSlot,
      selectedEventId,
      hasCopiedEvent,
      deleteEvent,
      duplicateEvent,
      copyEvent,
      cutEvent,
      pasteEvent,
      undo,
      redo,
      canUndo,
      canRedo,
      onToggleCommandMenu,
      onToggleSidebar,
      onToggleContextPanel,
      onCycleTheme,
      onOpenSettings,
      onGoToDate,
      onShowShortcuts,
      onTravelToTimeZone,
      travelTimeZone,
      travelToTimeZone,
      onMeetWith,
      onShowTeammateCalendar,
    };
  }, [
    goToToday,
    goToPrev,
    goToNext,
    switchView,
    setNumberOfDays,
    clearSelection,
    toggleWeekends,
    zoomHoursIn,
    zoomHoursOut,
    resetHourHeight,
    addEventAtNextSlot,
    selectedEventId,
    hasCopiedEvent,
    deleteEvent,
    duplicateEvent,
    copyEvent,
    cutEvent,
    pasteEvent,
    undo,
    redo,
    canUndo,
    canRedo,
    onToggleCommandMenu,
    onToggleSidebar,
    onToggleContextPanel,
    onCycleTheme,
    onOpenSettings,
    onGoToDate,
    onShowShortcuts,
    onTravelToTimeZone,
    travelTimeZone,
    travelToTimeZone,
    onMeetWith,
    onShowTeammateCalendar,
  ]);

  React.useEffect(() => {
    if (!enabled) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (handleAppShortcut(e, actionsRef.current)) return;
      if (handleEditShortcut(e, actionsRef.current)) return;
      handleShortcut(e, actionsRef.current);
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [enabled]);
}

import * as React from "react";

interface UseControllableStateOptions<T> {
  /** Controlled value. `undefined` lets the hook own the value */
  prop: T | undefined;
  /** Initial value (or lazy initializer) when not controlled */
  defaultProp: T | (() => T);
  /** Called with every new value, controlled or not */
  onChange?: (value: T) => void;
}

type UseControllableStateReturn<T> = [
  T,
  (action: React.SetStateAction<T>) => void,
];

/** Whether a state action is an updater function rather than a value */
function isUpdater<T>(
  action: React.SetStateAction<T>,
): action is (prev: T) => T {
  return typeof action === "function";
}

/**
 * State that can be controlled by a parent (`prop` + `onChange`) or owned by
 * the component (`defaultProp`), shadcn/Radix style. The setter accepts a
 * value or an updater, like `useState`, and skips no-op updates.
 */
export function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateOptions<T>): UseControllableStateReturn<T> {
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultProp);
  const isControlled = prop !== undefined;
  const value = prop !== undefined ? prop : uncontrolledValue;

  /** Latest value, read by updaters called outside render */
  const valueRef = React.useRef(value);
  const onChangeRef = React.useRef(onChange);

  React.useEffect(() => {
    valueRef.current = value;
  }, [value]);

  React.useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);

  const setValue = React.useCallback(
    (action: React.SetStateAction<T>) => {
      const next = isUpdater(action) ? action(valueRef.current) : action;
      if (Object.is(next, valueRef.current)) return;
      if (!isControlled) {
        // Owned value: later updaters in the same tick build on this one
        valueRef.current = next;
        setUncontrolledValue(next);
      }
      onChangeRef.current?.(next);
    },
    [isControlled],
  );

  return [value, setValue];
}

"use client";

import { useCallback } from "react";

import { useCalendar, useCalendarConfig } from "@/components/calendar-provider";
import { getKeyboardEventChange } from "@/lib/event-utils";
import { findEventOrOccurrence } from "@/lib/recurrence";

interface UseEventKeyboardOptions {
  /** Element holding the view's events; focus is put back on an event inside it */
  containerRef: React.RefObject<HTMLElement | null>;
  /** Vertically scrolling element, kept scrolled to the focused event */
  scrollContainerRef?: React.RefObject<HTMLElement | null>;
  /** Whether a day is on screen; a keyboard move off screen calls `revealDay` */
  isDayVisible: (date: Date) => boolean;
  /** Navigates the view so the day is on screen */
  revealDay: (date: Date) => void;
}

/** Arrow keys that, with Alt, move (or with Alt+Shift, resize) the focused event */
const EVENT_MOVE_KEYS = new Set([
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
]);

/**
 * Keys that select, open or close the focused event. Opening or closing its
 * popover can re-create the event's element, so focus is put back on it.
 */
const FOCUS_KEEPING_KEYS = new Set(["Enter", " ", "Escape"]);

/**
 * Focuses the event's element inside `container` and returns it, or `null`
 * when none takes focus. Inert (off-screen buffer) copies refuse focus, so
 * each match is tried in turn.
 */
export function focusEventElement(
  container: HTMLElement | null,
  eventId: string,
): HTMLElement | null {
  if (!container) return null;
  const candidates = container.querySelectorAll<HTMLElement>(
    `[data-event-id="${CSS.escape(eventId)}"]`,
  );
  for (const candidate of candidates) {
    candidate.focus({ preventScroll: true });
    if (document.activeElement === candidate) return candidate;
  }
  return null;
}

/** Scrolls `scroller` vertically just enough to show `element` */
function keepInView(element: HTMLElement, scroller: HTMLElement | null) {
  if (!scroller) return;
  const elementRect = element.getBoundingClientRect();
  const scrollerRect = scroller.getBoundingClientRect();
  if (elementRect.top < scrollerRect.top) {
    scroller.scrollTop -= scrollerRect.top - elementRect.top;
    return;
  }
  if (elementRect.bottom > scrollerRect.bottom) {
    scroller.scrollTop += elementRect.bottom - scrollerRect.bottom;
  }
}

/**
 * Keyboard editing for a view's events, as a keydown handler for the view's
 * root. On a focused event (an element with `data-event-id`):
 *
 * - Alt+ArrowLeft/Right moves it a day (over a hidden weekend);
 *   Alt+ArrowUp/Down moves it one
 *   `snapMinutes` step (a week in month view); Alt+Shift+ArrowUp/Down
 *   resizes its end (see `getKeyboardEventChange`)
 * - Enter, Space and Escape keep focus on it while its popover opens or closes
 *
 * Handled keys don't reach the calendar shortcuts (where arrows change the
 * period) or the browser (where Alt+Arrow navigates history).
 */
export function useEventKeyboard({
  containerRef,
  scrollContainerRef,
  isDayVisible,
  revealDay,
}: UseEventKeyboardOptions): (e: React.KeyboardEvent<HTMLElement>) => void {
  const { events, view, viewSettings, updateEvent } = useCalendar();
  const { showWeekends } = viewSettings;
  const config = useCalendarConfig();

  /**
   * After React re-renders, focuses the event's element again if focus was
   * lost (its element was re-created), and keeps it scrolled into view.
   * Focus that moved somewhere else on purpose is left alone. (Escape with
   * the popover open is handled by the popover: it closes first.)
   */
  const restoreFocus = useCallback(
    (eventId: string) => {
      requestAnimationFrame(() => {
        const container = containerRef.current;
        if (!container) return;
        const scroller = scrollContainerRef?.current ?? null;

        const active = document.activeElement;
        if (
          active instanceof HTMLElement &&
          active.dataset.eventId === eventId
        ) {
          keepInView(active, scroller);
          return;
        }
        if (active && active !== document.body) return;

        const focused = focusEventElement(container, eventId);
        if (focused) keepInView(focused, scroller);
      });
    },
    [containerRef, scrollContainerRef],
  );

  return useCallback(
    (e: React.KeyboardEvent<HTMLElement>) => {
      if (!(e.target instanceof HTMLElement)) return;
      const eventId =
        e.target.closest<HTMLElement>("[data-event-id]")?.dataset.eventId;
      if (!eventId) return;

      if (FOCUS_KEEPING_KEYS.has(e.key)) {
        restoreFocus(eventId);
        return;
      }
      if (!e.altKey || e.ctrlKey || e.metaKey) return;
      if (!EVENT_MOVE_KEYS.has(e.key)) return;

      e.preventDefault();
      e.stopPropagation();

      const event = findEventOrOccurrence(events, eventId, config.timeZone);
      if (!event) return;
      const changed = getKeyboardEventChange(
        event,
        e.key,
        e.shiftKey,
        view,
        config,
        showWeekends,
      );
      if (!changed) return;

      updateEvent(changed);
      if (!isDayVisible(changed.start)) revealDay(changed.start);
      restoreFocus(eventId);
    },
    [
      events,
      view,
      config,
      showWeekends,
      updateEvent,
      isDayVisible,
      revealDay,
      restoreFocus,
    ],
  );
}

import * as React from "react";
import { startOfDay } from "date-fns";

import { toZonedWallClock } from "@/lib/time-zones";

/**
 * Milliseconds between clock ticks. Ticks land on multiples of this value
 * (minute boundaries), so the current-time line moves when the minute does.
 */
const NOW_TICK_INTERVAL_MS = 60_000;

/** Components subscribed to the shared clock. */
const listeners = new Set<() => void>();

/** Timestamp handed to subscribers. Refreshed on every tick. */
let nowSnapshot: number | null = null;

/** Pending tick, or `null` while nothing is subscribed. */
let tickTimeout: ReturnType<typeof setTimeout> | null = null;

/** Returns the index of the tick interval a timestamp falls in. */
function getTickIndex(timestamp: number): number {
  return Math.floor(timestamp / NOW_TICK_INTERVAL_MS);
}

/**
 * Returns the shared "now" timestamp.
 *
 * The value stays the same within one tick interval, so repeated reads during
 * a render agree with each other. It is refreshed lazily when a read lands in
 * a later interval, which covers renders that happen while nothing is
 * subscribed (and so no timer is running).
 */
function readNow(): number {
  const current = Date.now();
  if (
    nowSnapshot === null ||
    getTickIndex(current) !== getTickIndex(nowSnapshot)
  ) {
    nowSnapshot = current;
  }
  return nowSnapshot;
}

/** "Now" on the last zone's clock read, kept for the tick it was read in */
let zonedNowCache: { now: number; timeZone: string; value: number } | null =
  null;

/**
 * The shared "now" on a clock in `timeZone`, as `toZonedWallClock` gives it,
 * or the shared "now" itself without a zone. One zone conversion per tick.
 */
function readZonedNow(timeZone: string | undefined): number {
  const now = readNow();
  if (!timeZone) return now;
  if (zonedNowCache?.now === now && zonedNowCache.timeZone === timeZone) {
    return zonedNowCache.value;
  }
  const value = toZonedWallClock(new Date(now), timeZone).getTime();
  zonedNowCache = { now, timeZone, value };
  return value;
}

/** Schedules the next tick on the next interval boundary. */
function scheduleTick(): void {
  const delay = NOW_TICK_INTERVAL_MS - (Date.now() % NOW_TICK_INTERVAL_MS);
  tickTimeout = setTimeout(() => {
    nowSnapshot = Date.now();
    listeners.forEach((listener) => listener());
    scheduleTick();
  }, delay);
}

/** Subscribes to the shared clock. One timer serves every subscriber. */
function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  if (tickTimeout === null) {
    scheduleTick();
  }

  return () => {
    listeners.delete(listener);
    if (listeners.size > 0 || tickTimeout === null) return;
    clearTimeout(tickTimeout);
    tickTimeout = null;
  };
}

function getNowSnapshot(): number {
  return readNow();
}

/**
 * Server and hydration snapshot. `null` means "the time is not known yet",
 * so nothing that depends on the clock or the viewer's timezone is rendered
 * and server and client markup match (React error #418).
 */
function getServerSnapshot(): null {
  return null;
}

/** Server and hydration snapshot for `useIsPast`: nothing is past yet. */
function getServerIsPastSnapshot(): boolean {
  return false;
}

/**
 * Returns the current time, updated on every minute boundary.
 *
 * Returns `null` during server rendering and hydration, and the real time
 * right after hydration. Client-only renders get the real time on the first
 * render. Components must render their time-dependent parts only when the
 * value is not `null`.
 *
 * Give it the calendar's zone (`useCalendarConfig().timeZone`) to read the
 * clock there: the date is then on that zone's clock, like the events the
 * views draw.
 */
export function useNow(timeZone?: string): Date | null {
  const timestamp = React.useSyncExternalStore<number | null>(
    subscribe,
    getNowSnapshot,
    getServerSnapshot,
  );

  return React.useMemo(
    () =>
      timestamp === null
        ? null
        : toZonedWallClock(new Date(timestamp), timeZone),
    [timestamp, timeZone],
  );
}

/**
 * Returns the start of the viewer's current day, or `null` during server
 * rendering and hydration.
 *
 * Shares the clock with `useNow`, but the component re-renders only when the
 * day changes, not on every tick. Give it the calendar's zone
 * (`useCalendarConfig().timeZone`) for that zone's today, as a local
 * midnight like the days the views draw.
 */
export function useToday(timeZone?: string): Date | null {
  const getSnapshot = React.useCallback(
    () => startOfDay(readZonedNow(timeZone)).getTime(),
    [timeZone],
  );
  const timestamp = React.useSyncExternalStore<number | null>(
    subscribe,
    getSnapshot,
    getServerSnapshot,
  );

  return React.useMemo(
    () => (timestamp === null ? null : new Date(timestamp)),
    [timestamp],
  );
}

/**
 * Returns whether `date` is in the past.
 *
 * Returns `false` during server rendering and hydration. Shares the clock
 * with `useNow`, but the component re-renders only when the answer changes,
 * not on every tick. Give it the calendar's zone
 * (`useCalendarConfig().timeZone`) when `date` reads on that zone's clock,
 * like the events the views draw.
 */
export function useIsPast(date: Date, timeZone?: string): boolean {
  const timestamp = date.getTime();
  const getSnapshot = React.useCallback(
    () => timestamp < readZonedNow(timeZone),
    [timestamp, timeZone],
  );

  return React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    getServerIsPastSnapshot,
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";
import type { PointerGestureStart } from "@/components/week-view-types";

interface UsePointerGestureOptions {
  /**
   * Element the gestures start in. A no-op, non-passive touchmove listener
   * on it keeps the browser from treating its touch moves as uncancelable,
   * so a long press that became a drag can stop the page from scrolling.
   */
  containerRef: React.RefObject<HTMLElement | null>;
}

interface UsePointerGestureReturn {
  /**
   * Starts a press-to-drag gesture from a pointerdown. Mouse and pen start
   * right away; touch starts after a long press, so a finger that moves
   * first scrolls the page instead. Non-primary pointers and buttons are
   * ignored.
   */
  startGesture: (
    e: React.PointerEvent<HTMLElement>,
    onStart: (start: PointerGestureStart) => void,
  ) => void;
}

/** How long (ms) a finger must rest before a touch drag, resize or create starts */
export const LONG_PRESS_DELAY_MS = 350;

/**
 * How far (px) a finger may move during the long press. Moving further
 * cancels it, so the gesture scrolls instead.
 */
export const LONG_PRESS_MOVE_TOLERANCE_PX = 8;

/**
 * How long (ms) after a touch gesture ends its follow-up mousedown, click
 * and long-press context menu are swallowed. Mouse and pen clicks follow
 * pointerup in the same task, so for them the window closes on the next one.
 */
const TOUCH_FOLLOW_UP_WINDOW_MS = 400;

/** A touch waiting for its long press, or a long press that started a gesture */
interface TouchPress {
  pointerId: number;
  startClientX: number;
  startClientY: number;
  /** Latest position, where the gesture starts when the long press completes */
  lastClientX: number;
  lastClientY: number;
  element: HTMLElement;
  /**
   * Node the touch events target. Browsers keep sending them there even
   * after it is removed from the DOM mid-drag, when they no longer bubble.
   */
  touchTarget: EventTarget;
  /** Whether the long press completed and the gesture is running */
  isActive: boolean;
  /** The element's inline touch-action before the gesture, restored after it */
  previousTouchAction: string;
  timer: ReturnType<typeof setTimeout> | null;
}

/** Whether a pointerdown can start a gesture: the primary pointer's main button (left mouse button, pen tip or a finger) */
export function isPrimaryPress(e: React.PointerEvent | PointerEvent): boolean {
  return e.isPrimary && e.button === 0;
}

/** Swallows the next `type` event the browser sends within `windowMs` */
function swallowNext(type: "click" | "mousedown", windowMs: number): void {
  const stop = () => {
    window.removeEventListener(type, swallow, true);
    clearTimeout(timer);
  };
  function swallow(e: Event) {
    e.preventDefault();
    e.stopPropagation();
    stop();
  }
  window.addEventListener(type, swallow, true);
  const timer = setTimeout(stop, windowMs);
}

/**
 * Swallows the click the browser sends right after a drag, resize or touch
 * gesture ends. When the pressed element was swapped out mid-drag (for a
 * ghost or a floating copy), that click lands on a shared ancestor and would
 * read as a background click that clears the selection.
 */
export function suppressNextClick(pointerType: string): void {
  swallowNext("click", pointerType === "touch" ? TOUCH_FOLLOW_UP_WINDOW_MS : 0);
}

/** Keeps the long-press context menu from opening over a touch gesture */
function blockContextMenu(e: Event) {
  e.preventDefault();
  e.stopPropagation();
}

/** Registered only to make touch moves in the container cancelable */
function noop() {}

/**
 * Turns pointerdowns into press-to-drag gestures for the drag and resize
 * hooks: immediately for mouse and pen, after a long press for touch.
 * While a touch gesture runs, the pressed element gets `touch-action: none`,
 * page scrolling and the context menu are blocked, and the click that
 * follows it is swallowed.
 */
export function usePointerGesture({
  containerRef,
}: UsePointerGestureOptions): UsePointerGestureReturn {
  const pressRef = useRef<TouchPress | null>(null);
  const handlePressMoveRef = useRef<((e: PointerEvent) => void) | null>(null);
  const handlePressEndRef = useRef<((e: PointerEvent) => void) | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    container.addEventListener("touchmove", noop, { passive: false });
    return () => container.removeEventListener("touchmove", noop);
  }, [containerRef]);

  /** Stops the page from scrolling once the long press has completed */
  const blockTouchMove = useCallback((e: Event) => {
    if (!pressRef.current?.isActive || !e.cancelable) return;
    e.preventDefault();
  }, []);

  /** Ends the current touch press, whether it was pending or active */
  const finishPress = useCallback(() => {
    const press = pressRef.current;
    if (!press) return;
    pressRef.current = null;

    if (press.timer !== null) clearTimeout(press.timer);
    if (handlePressMoveRef.current) {
      window.removeEventListener("pointermove", handlePressMoveRef.current);
    }
    if (handlePressEndRef.current) {
      window.removeEventListener("pointerup", handlePressEndRef.current);
      window.removeEventListener("pointercancel", handlePressEndRef.current);
    }
    press.touchTarget.removeEventListener("touchmove", blockTouchMove);

    if (!press.isActive) return;
    press.element.style.touchAction = press.previousTouchAction;
    // The browser may still send the touch's compatibility mousedown and
    // click. The mousedown would move focus (e.g. off a just-created
    // event's title) and the click would read as a background click.
    swallowNext("mousedown", TOUCH_FOLLOW_UP_WINDOW_MS);
    suppressNextClick("touch");
    setTimeout(() => {
      window.removeEventListener("contextmenu", blockContextMenu, true);
    }, TOUCH_FOLLOW_UP_WINDOW_MS);
  }, [blockTouchMove]);

  useEffect(() => {
    handlePressMoveRef.current = (e: PointerEvent) => {
      const press = pressRef.current;
      if (!press || e.pointerId !== press.pointerId) return;
      press.lastClientX = e.clientX;
      press.lastClientY = e.clientY;
      if (press.isActive) return;

      const distance = Math.hypot(
        e.clientX - press.startClientX,
        e.clientY - press.startClientY,
      );
      if (distance <= LONG_PRESS_MOVE_TOLERANCE_PX) return;
      // Moved before the long press completed: let the browser scroll
      finishPress();
    };

    handlePressEndRef.current = (e: PointerEvent) => {
      const press = pressRef.current;
      if (!press || e.pointerId !== press.pointerId) return;
      finishPress();
    };
  }, [finishPress]);

  // Cancel a pending or running touch press on unmount
  useEffect(() => {
    return finishPress;
  }, [finishPress]);

  const startGesture = useCallback(
    (
      e: React.PointerEvent<HTMLElement>,
      onStart: (start: PointerGestureStart) => void,
    ) => {
      if (!isPrimaryPress(e)) return;

      const element = e.currentTarget;
      if (e.pointerType !== "touch") {
        onStart({
          clientX: e.clientX,
          clientY: e.clientY,
          pointerId: e.pointerId,
          pointerType: e.pointerType,
          element,
        });
        return;
      }

      finishPress();
      const press: TouchPress = {
        pointerId: e.pointerId,
        startClientX: e.clientX,
        startClientY: e.clientY,
        lastClientX: e.clientX,
        lastClientY: e.clientY,
        element,
        touchTarget: e.target,
        isActive: false,
        previousTouchAction: "",
        timer: null,
      };
      pressRef.current = press;

      press.touchTarget.addEventListener("touchmove", blockTouchMove, {
        passive: false,
      });
      if (handlePressMoveRef.current) {
        window.addEventListener("pointermove", handlePressMoveRef.current);
      }
      if (handlePressEndRef.current) {
        window.addEventListener("pointerup", handlePressEndRef.current);
        window.addEventListener("pointercancel", handlePressEndRef.current);
      }

      press.timer = setTimeout(() => {
        press.timer = null;
        press.isActive = true;
        press.previousTouchAction = element.style.touchAction;
        element.style.touchAction = "none";
        window.addEventListener("contextmenu", blockContextMenu, true);
        onStart({
          clientX: press.lastClientX,
          clientY: press.lastClientY,
          pointerId: press.pointerId,
          pointerType: "touch",
          element,
        });
      }, LONG_PRESS_DELAY_MS);
    },
    [finishPress, blockTouchMove],
  );

  return { startGesture };
}

import * as React from "react";

import { getTimeZoneDisplayName, getTimeZoneLabel } from "@/lib/timezone-label";

/**
 * Label rendered on the server and during hydration. It must not depend on
 * the runtime's timezone, or server and client markup would differ (#418).
 */
const SERVER_TIMEZONE_LABEL = "";

/** No-op subscription: the label is re-read on every client render. */
function subscribe(): () => void {
  return () => {};
}

function getServerSnapshot(): string {
  return SERVER_TIMEZONE_LABEL;
}

/**
 * Returns the short timezone label ("EDT", "GMT-3", "GMT+5:30") of
 * `timeZone`, the viewer's zone by default.
 *
 * Server rendering and the client's hydration render both return
 * `SERVER_TIMEZONE_LABEL`, so the markup matches. React then re-renders
 * with the client snapshot right after hydration. Client-only renders
 * (no SSR) get the real label on the first render.
 */
export function useTimeZoneLabel(timeZone?: string): string {
  const getClientSnapshot = React.useCallback(
    () => getTimeZoneLabel(new Date(), timeZone),
    [timeZone],
  );
  return React.useSyncExternalStore(
    subscribe,
    getClientSnapshot,
    getServerSnapshot,
  );
}

/**
 * Returns the timezone label with its city ("GMT-3 Sao Paulo", "EDT New
 * York") of `timeZone`, the viewer's zone by default. Like
 * `useTimeZoneLabel`, it is empty on the server and during hydration.
 */
export function useTimeZoneDisplayName(timeZone?: string): string {
  const getClientSnapshot = React.useCallback(
    () => getTimeZoneDisplayName(new Date(), timeZone),
    [timeZone],
  );
  return React.useSyncExternalStore(
    subscribe,
    getClientSnapshot,
    getServerSnapshot,
  );
}

