];

/** Milliseconds in a day, for times of day */
const DAY_MS = 86_400_000;

/** Milliseconds in an hour */
const HOUR_MS = 3_600_000;

/**
 * Hour of the day whose offsets the time axis's second column follows:
 * noon, clear of the night hours when clocks change
 */
const SECONDARY_TIME_AXIS_HOUR = 12;

/** One `Intl.DateTimeFormat` per zone and name style; building them is slow */
const formatterCache = new Map<string, Intl.DateTimeFormat>();

/** The runtime's zones, listed once: `Intl.supportedValuesOf` builds a new array each call */
let supportedTimeZones: string[] | null = null;

/** Zone of each legacy label `findTimeZoneByLabel` has looked up */
const labelTimeZoneCache = new Map<string, string | undefined>();

/** Whether the runtime knows each zone name `isKnownTimeZone` has checked */
const knownTimeZoneCache = new Map<string, boolean>();

/**
 * Each event's copy on a zone's clock (`toDisplayEvent`), by event, so an
 * unchanged event keeps the same copy from one render to the next
 */
const displayEventCache = new WeakMap<
  CalendarEvent,
  { timeZone: string; event: CalendarEvent }
>();

/**
 * The event each copy `toDisplayEvent` made came from, so
 * `fromDisplayEvent` gives back the exact instants of an unchanged copy
 */
const storedEventCache = new WeakMap<
  CalendarEvent,
  { timeZone: string; event: CalendarEvent }
>();

function getFormatter(
  timeZone: string,
  timeZoneName: Intl.DateTimeFormatOptions["timeZoneName"],
): Intl.DateTimeFormat {
  const key = `${timeZone}|${timeZoneName}`;
  const cached = formatterCache.get(key);
  if (cached) return cached;

  const formatter = new Intl.DateTimeFormat(TIME_ZONE_LOCALE, {
    timeZone,
    timeZoneName,
  });
  formatterCache.set(key, formatter);
  return formatter;
}

function getZoneNamePart(
  date: Date,
  timeZone: string,
  timeZoneName: Intl.DateTimeFormatOptions["timeZoneName"],
): string {
  return (
    getFormatter(timeZone, timeZoneName)
      .formatToParts(date)
      .find((part) => part.type === "timeZoneName")?.value ?? ""
  );
}

/** Whether `name` is only an offset ("GMT-03:00", "GMT"), not a real name */
function isOffsetName(name: string): boolean {
  return /^(GMT|UTC)([+-]\d|$)/.test(name);
}

/**
 * Returns the viewer's IANA time zone, e.g. "America/Sao_Paulo"
 */
export function getViewerTimeZone(): string {
  return Intl.DateTimeFormat().resolvedOptions().timeZone;
}

/**
 * Returns every IANA zone the runtime knows, or a short list of common ones
 * when it can't enumerate them
 */
export function getSupportedTimeZones(): string[] {
  if (supportedTimeZones) return supportedTimeZones;
  supportedTimeZones =
    typeof Intl.supportedValuesOf === "function"
      ? Intl.supportedValuesOf("timeZone")
      : FALLBACK_TIME_ZONES;
  return supportedTimeZones;
}

/**
 * Returns the offset of `timeZone` from UTC at `date`, in minutes: -180 for
 * São Paulo, 330 for Kolkata
 */
export function getTimeZoneOffsetMinutes(date: Date, timeZone: string): number {
  // "GMT-03:00", "GMT+05:30", or "GMT" for UTC itself
  const match = /GMT([+-])(\d{2}):(\d{2})/.exec(
    getZoneNamePart(date, timeZone, "longOffset"),
  );
  if (!match) return 0;

  const minutes = Number(match[2]) * 60 + Number(match[3]);
  return match[1] === "-" ? -minutes : minutes;
}

/**
 * Minutes a clock in `toTimeZone` is ahead of a clock in `fromTimeZone` at
 * `date`: 570 from New York to Kolkata in June (GMT−4 to GMT+5:30), -180
 * from New York to Los Angeles. Negative when it is behind.
 */
export function getTimeZoneOffsetDifference(
  date: Date,
  fromTimeZone: string,
  toTimeZone: string,
): number {
  return (
    getTimeZoneOffsetMinutes(date, toTimeZone) -
    getTimeZoneOffsetMinutes(date, fromTimeZone)
  );
}

/**
 * Formats an offset the way the picker lists it: "GMT−03:00", "GMT+05:30",
 * "GMT+00:00"
 */
export function formatLongOffset(offsetMinutes: number): string {
  const sign = offsetMinutes < 0 ? MINUS_SIGN : "+";
  const total = Math.abs(offsetMinutes);
  const hours = String(Math.floor(total / 60)).padStart(2, "0");
  const minutes = String(total % 60).padStart(2, "0");
  return `GMT${sign}${hours}:${minutes}`;
}

/**
 * Formats an offset the way the details row shows it: "GMT−3", "GMT+5:30",
 * "GMT+0"
 */
export function formatShortOffset(offsetMinutes: number): string {
  const sign = offsetMinutes < 0 ? MINUS_SIGN : "+";
  const total = Math.abs(offsetMinutes);
  const minutes = total % 60;
  const hours = Math.floor(total / 60);
  if (minutes === 0) return `GMT${sign}${hours}`;
  return `GMT${sign}${hours}:${String(minutes).padStart(2, "0")}`;
}

/**
 * Returns the zone's English name at `date` ("Brasilia Standard Time",
 * "Eastern Daylight Time"). Zones the platform has no name for get their
 * generic name ("Punta Arenas Time"), else their IANA id.
 */
export function getTimeZoneName(date: Date, timeZone: string): string {
  const long = getZoneNamePart(date, timeZone, "long");
  if (long && !isOffsetName(long)) return long;

  const generic = getZoneNamePart(date, timeZone, "longGeneric");
  if (generic && !isOffsetName(generic)) return generic;

  return timeZone;
}

/**
 * Describes one zone for the picker at `date`
 */
export function getTimeZoneOption(
  date: Date,
  timeZone: string,
): TimeZoneOption {
  const offsetMinutes = getTimeZoneOffsetMinutes(date, timeZone);
  return {
    id: timeZone,
    offsetMinutes,
    offsetLabel: formatLongOffset(offsetMinutes),
    name: getTimeZoneName(date, timeZone),
    city: getTimeZoneCity(timeZone) || timeZone,
  };
}

/**
 * Returns every zone for the picker at `date`, sorted by offset and then by
 * IANA id, as Notion Calendar lists them
 */
export function getTimeZoneOptions(date: Date): TimeZoneOption[] {
  return getSupportedTimeZones()
    .map((timeZone) => getTimeZoneOption(date, timeZone))
    .sort(
      (a, b) => a.offsetMinutes - b.offsetMinutes || a.id.localeCompare(b.id),
    );
}

/**
 * The row's label for a zone: "GMT−3" and "Sao Paulo"
 */
export function getTimeZoneRowLabel(
  date: Date,
  timeZone: string,
): { offset: string; city: string } {
  return {
    offset: formatShortOffset(getTimeZoneOffsetMinutes(date, timeZone)),
    city: getTimeZoneCity(timeZone) || timeZone,
  };
}

/**
 * The IANA zone a legacy label like "GMT-3 Sao Paulo" names, found by its
 * city. `undefined` when the label names no known city.
 */
export function findTimeZoneByLabel(
  label: string | undefined,
): string | undefined {
  if (!label) return undefined;
  if (labelTimeZoneCache.has(label)) return labelTimeZoneCache.get(label);

  const city = normalizeSearchText(label.slice(label.indexOf(" ") + 1).trim());
  const timeZone = city
    ? getSupportedTimeZones().find(
        (zone) => normalizeSearchText(getTimeZoneCity(zone)) === city,
      )
    : undefined;
  labelTimeZoneCache.set(label, timeZone);
  return timeZone;
}

/**
 * Whether the runtime knows `timeZone` as a zone name. `Intl` throws a
 * RangeError on one it doesn't know, like "Mars/Olympus" or Outlook's
 * "Pacific Standard Time".
 */
export function isKnownTimeZone(timeZone: string): boolean {
  const cached = knownTimeZoneCache.get(timeZone);
  if (cached !== undefined) return cached;

  let isKnown = true;
  try {
    getFormatter(timeZone, "longOffset");
  } catch {
    isKnown = false;
  }
  knownTimeZoneCache.set(timeZone, isKnown);
  return isKnown;
}

/**
 * The IANA zone an event is set in: its `timeZone`, else the zone its
 * legacy `timezone` label names. `undefined` means the viewer's zone, which
 * is also what a `timeZone` the runtime doesn't know falls back to.
 */
export function getEventTimeZone(
  event: Pick<DetailedCalendarEvent, "timeZone" | "timezone">,
): string | undefined {
  if (event.timeZone && isKnownTimeZone(event.timeZone)) return event.timeZone;
  return findTimeZoneByLabel(event.timezone);
}

/** Lower case without accents, so "sao" finds "São" */
export function normalizeSearchText(text: string): string {
  return text.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
}

/**
 * The offset an offset-like query names, in minutes: "+9", "GMT+9",
 * "utc-3", "−03:00", "+5:30". `null` for any other text.
 */
export function parseOffsetQuery(query: string): number | null {
  const match =
    /^(?:gmt|utc)?\s*([+\-\u2212])\s*(\d{1,2})(?::?(\d{2}))?$/i.exec(
      query.trim(),
    );
  if (!match) return null;
  const minutes = Number(match[2]) * 60 + Number(match[3] ?? 0);
  return match[1] === "+" ? minutes : -minutes;
}

/**
 * Zones whose name, city or IANA id contains `query`, ignoring case and
 * accents, or whose offset it names ("+9", "GMT-3", "+05:30"). Zones at
 * that offset come first, then the ones matching their city, their name,
 * then their id; each group keeps the list's order.
 */
export function searchTimeZones(
  options: TimeZoneOption[],
  query: string,
): TimeZoneOption[] {
  const needle = normalizeSearchText(query.trim());
  if (!needle) return options;
  const offset = parseOffsetQuery(query);

  const byOffset: TimeZoneOption[] = [];
  const byCity: TimeZoneOption[] = [];
  const byName: TimeZoneOption[] = [];
  const byId: TimeZoneOption[] = [];
  for (const option of options) {
    if (offset !== null && option.offsetMinutes === offset) {
      byOffset.push(option);
    } else if (normalizeSearchText(option.city).includes(needle)) {
      byCity.push(option);
    } else if (normalizeSearchText(option.name).includes(needle)) {
      byName.push(option);
    } else if (normalizeSearchText(option.id).includes(needle)) {
      byId.push(option);
    }
  }
  return [...byOffset, ...byCity, ...byName, ...byId];
}

/**
 * Splits `text` around the first match of `query` (ignoring case and
 * accents), so the picker can bold it. Returns the whole text as `before`
 * when there is no match.
 */
export function splitSearchMatch(
  text: string,
  query: string,
): { before: string; match: string; after: string } {
  const needle = normalizeSearchText(query.trim());
  // Normalized one character at a time, so indexes still line up with `text`
  const haystack = Array.from(text)
    .map((char) => normalizeSearchText(char) || char)
    .join("");
  const index = needle ? haystack.indexOf(needle) : -1;
  if (index === -1 || haystack.length !== text.length) {
    return { before: text, match: "", after: "" };
  }
  return {
    before: text.slice(0, index),
    match: text.slice(index, index + needle.length),
    after: text.slice(index + needle.length),
  };
}

/**
 * The wall-clock time of `date` in `timeZone`, as milliseconds of a UTC
 * date that reads the same
 */
function getWallClock(date: Date, timeZone: string): number {
  const offset = getTimeZoneOffsetMinutes(date, timeZone);
  return date.getTime() + offset * 60_000;
}

/**
 * The instant the clock in `timeZone` reads `wallClock` (milliseconds of a
 * UTC date that reads the same). `near` is an instant close to it.
 */
function fromWallClock(wallClock: number, timeZone: string, near: Date): Date {
  // The offset depends on the instant, which depends on the offset: guess
  // with the offset near it, then correct once (DST)
  const guess = wallClock - getTimeZoneOffsetMinutes(near, timeZone) * 60_000;
  const corrected =
    wallClock - getTimeZoneOffsetMinutes(new Date(guess), timeZone) * 60_000;
  return new Date(corrected);
}

/**
 * `date` as a calendar drawn in `timeZone` shows it: a Date whose local time
 * (`getHours()`, date-fns `format`) reads the clock in `timeZone` at that
 * instant, so 9 PM in Tokyo comes back as 9 PM local in any viewer's zone.
 * `date` itself without a zone. A time the viewer's own clocks skip can't be
 * a local time: it comes back an hour later.
 */
export function toZonedWallClock(date: Date, timeZone?: string): Date {
  if (!timeZone) return date;
  const wallClock = new Date(getWallClock(date, timeZone));
  return new Date(
    wallClock.getUTCFullYear(),
    wallClock.getUTCMonth(),
    wallClock.getUTCDate(),
    wallClock.getUTCHours(),
    wallClock.getUTCMinutes(),
    wallClock.getUTCSeconds(),
    wallClock.getUTCMilliseconds(),
  );
}

/**
 * The instant a clock in `timeZone` reads the local time of `date`: the
 * inverse of `toZonedWallClock`. A time the zone's clocks skip lands after
 * the gap (1:30 AM on a spring-forward night is 2:30 AM), and one they show
 * twice is the first of the two, as `new Date(...)` does with local times.
 * `date` itself without a zone.
 */
export function fromZonedWallClock(date: Date, timeZone?: string): Date {
  if (!timeZone) return date;
  const wallClock = Date.UTC(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
    date.getHours(),
    date.getMinutes(),
    date.getSeconds(),
    date.getMilliseconds(),
  );
  // The offsets a day before and a day after: each one that reads back as
  // `wallClock` gives an instant (both, when the time happens twice)
  const offsetBefore = getTimeZoneOffsetMinutes(
    new Date(wallClock - DAY_MS),
    timeZone,
  );
  const offsetAfter = getTimeZoneOffsetMinutes(
    new Date(wallClock + DAY_MS),
    timeZone,
  );
  const instants = [offsetBefore, offsetAfter]
    .map((offset) => wallClock - offset * 60_000)
    .filter(
      (instant) => getWallClock(new Date(instant), timeZone) === wallClock,
    );
  if (instants.length > 0) return new Date(Math.min(...instants));
  // Skipped: read with the offset from before the change, which lands after
  // the gap
  return new Date(wallClock - offsetBefore * 60_000);
}

/**
 * The current time on a clock in `timeZone`, as `toZonedWallClock` gives it:
 * "now" and "today" for a calendar drawn in that zone. The current time
 * itself without a zone.
 */
export function getZonedNow(timeZone?: string): Date {
  return toZonedWallClock(new Date(), timeZone);
}

/**
 * An event as a calendar drawn in `timeZone` draws it: a timed event's
 * `start` and `end` as `toZonedWallClock` gives them. All-day events are
 * calendar dates already, so they come back as they are, as does every
 * event when `timeZone` is unset. The same event object gives back the same
 * copy, so don't change an event in place.
 */
export function toDisplayEvent<TEvent extends CalendarEvent>(
  event: TEvent,
  timeZone?: string,
): TEvent {
  if (!timeZone || event.isAllDay) return event;
  const cached = displayEventCache.get(event);
  // Built from this same object, so it is a `TEvent`
  if (cached?.timeZone === timeZone) return cached.event as TEvent;
  const shown: TEvent = {
    ...event,
    start: toZonedWallClock(event.start, timeZone),
    end: toZonedWallClock(event.end, timeZone),
  };
  displayEventCache.set(event, { timeZone, event: shown });
  storedEventCache.set(shown, { timeZone, event });
  return shown;
}

/**
 * The event to store after a calendar drawn in `timeZone` changed it: the
 * inverse of `toDisplayEvent`. A copy `toDisplayEvent` made and nothing
 * changed gives back the event it came from. Otherwise a timed event's
 * `start` and `end` go back to instants (`fromZonedWallClock`), and a time
 * that still reads as it did in `toDisplayEvent(storedEvent)` keeps the
 * stored instant, so a time the zone's clocks show twice, or one the
 * viewer's clocks skip, survives an edit of another field. All-day events
 * keep their calendar dates. The event itself when `timeZone` is unset.
 */
export function fromDisplayEvent<TEvent extends CalendarEvent>(
  shownEvent: TEvent,
  timeZone?: string,
  storedEvent?: TEvent,
): TEvent {
  if (!timeZone || shownEvent.isAllDay) return shownEvent;
  const source = storedEventCache.get(shownEvent);
  // Made from that same object, so it is a `TEvent`
  if (source?.timeZone === timeZone) return source.event as TEvent;
  // An all-day event's dates aren't instants: map a switch to timed in full
  const before = storedEvent && !storedEvent.isAllDay ? storedEvent : undefined;
  const shownBefore = before ? toDisplayEvent(before, timeZone) : undefined;
  const toInstant = (field: "start" | "end"): Date => {
    if (
      before &&
      shownBefore &&
      shownBefore[field].getTime() === shownEvent[field].getTime()
    ) {
      return before[field];
    }
    return fromZonedWallClock(shownEvent[field], timeZone);
  };
  return { ...shownEvent, start: toInstant("start"), end: toInstant("end") };
}

/**
 * A range on the calendar's clock (a `NewEventRange`, a `VisibleRange`) as
 * instants: what `createEvent` and `onVisibleRangeChange` get. The range
 * itself when `timeZone` is unset.
 */
export function fromDisplayRange<TRange extends { start: Date; end: Date }>(
  range: TRange,
  timeZone?: string,
): TRange {
  if (!timeZone) return range;
  return {
    ...range,
    start: fromZonedWallClock(range.start, timeZone),
    end: fromZonedWallClock(range.end, timeZone),
  };
}

/**
 * Moves `date` from one zone to another keeping its wall-clock time: 8 AM
 * in São Paulo becomes 8 AM in New York, as Notion Calendar does when an
 * event's zone changes
 */
export function changeTimeZoneKeepingWallClock(
  date: Date,
  fromTimeZone: string,
  toTimeZone: string,
): Date {
  if (fromTimeZone === toTimeZone) return date;
  return fromWallClock(getWallClock(date, fromTimeZone), toTimeZone, date);
}

/**
 * The calendar day `date` falls on in `timeZone` (the viewer's zone when
 * unset), as a local midnight: what a repeat rule counts its days in
 */
export function getZonedDay(date: Date, timeZone?: string): Date {
  if (!timeZone) {
    return new Date(date.getFullYear(), date.getMonth(), date.getDate());
  }
  const wallClock = new Date(getWallClock(date, timeZone));
  return new Date(
    wallClock.getUTCFullYear(),
    wallClock.getUTCMonth(),
    wallClock.getUTCDate(),
  );
}

/**
 * The time of day `date` shows on a clock in `timeZone` (the viewer's zone
 * when unset), in milliseconds since midnight
 */
export function getZonedTimeOfDay(date: Date, timeZone?: string): number {
  if (!timeZone) {
    const minutes = date.getHours() * 60 + date.getMinutes();
    return (minutes * 60 + date.getSeconds()) * 1000 + date.getMilliseconds();
  }
  return ((getWallClock(date, timeZone) % DAY_MS) + DAY_MS) % DAY_MS;
}

/**
 * The instant a clock in `timeZone` (the viewer's zone when unset) reads
 * `timeOfDay` milliseconds after midnight on `day`'s local calendar day
 */
export function fromZonedDayTime(
  day: Date,
  timeOfDay: number,
  timeZone?: string,
): Date {
  if (!timeZone) {
    return new Date(
      day.getFullYear(),
      day.getMonth(),
      day.getDate(),
      0,
      0,
      0,
      timeOfDay,
    );
  }
  const wallClock =
    Date.UTC(day.getFullYear(), day.getMonth(), day.getDate()) + timeOfDay;
  return fromWallClock(wallClock, timeZone, new Date(wallClock));
}

/**
 * The instant whose offsets the time axis's second column shows: noon in
 * `timeZone` (the zone of the hour rows) on today while today is among
 * `days`, else on the first of `days` (never empty). One instant serves the
 * whole column, so in a week where a clock changes, the labels are off by
 * that change on the days on the other side of it.
 */
export function getSecondaryTimeAxisInstant(
  days: readonly Date[],
  today: Date | null,
  timeZone: string,
): Date {
  const visibleToday = today
    ? days.find((day) => isSameDay(day, today))
    : undefined;
  return fromZonedDayTime(
    visibleToday ?? days[0],
    SECONDARY_TIME_AXIS_HOUR * HOUR_MS,
    timeZone,
  );
}

/**
 * Adds an additional zone, as the left-most column, as Notion Calendar's
 * "Show additional time zones" does. A zone already shown stays where it is.
 */
export function addTimeZone(
  zones: CalendarTimeZones,
  timeZone: string,
): CalendarTimeZones {
  if (zones.primary === timeZone || zones.secondary.includes(timeZone)) {
    return zones;
  }
  return { ...zones, secondary: [timeZone, ...zones.secondary] };
}

/**
 * Removes a zone ("Remove time zone from list"). Removing the primary one
 * makes the additional zone next to it primary; the only zone left stays.
 */
export function removeTimeZone(
  zones: CalendarTimeZones,
  timeZone: string,
): CalendarTimeZones {
  if (zones.primary !== timeZone) {
    return {
      ...zones,
      secondary: zones.secondary.filter((zone) => zone !== timeZone),
    };
  }
  const nextPrimary = zones.secondary[zones.secondary.length - 1];
  if (!nextPrimary) return zones;
  return { primary: nextPrimary, secondary: zones.secondary.slice(0, -1) };
}

/**
 * Makes a zone primary ("Make time zone primary", or "Add as primary time
 * zone" after travelling): it moves next to the days, the old primary zone
 * becomes the additional zone closest to it, and the others shift left.
 */
export function makeTimeZonePrimary(
  zones: CalendarTimeZones,
  timeZone: string,
): CalendarTimeZones {
  if (zones.primary === timeZone) return zones;
  const others = zones.secondary.filter((zone) => zone !== timeZone);
  return {
    primary: timeZone,
    secondary: zones.primary ? [...others, zones.primary] : others,
  };
}

/**
 * Makes the primary zone an additional one ("Make time zone secondary"):
 * the additional zone closest to it becomes primary. With no additional
 * zone, nothing changes.
 */
export function makeTimeZoneSecondary(
  zones: CalendarTimeZones,
): CalendarTimeZones {
  const closest = zones.secondary[zones.secondary.length - 1];
  if (!closest) return zones;
  return makeTimeZonePrimary(zones, closest);
}

/**
 * Puts another zone in a zone's place ("Change time zone"). An additional
 * zone already shown elsewhere moves there; changing one to the primary
 * zone removes it.
 */
export function replaceTimeZone(
  zones: CalendarTimeZones,
  timeZone: string,
  replacement: string,
): CalendarTimeZones {
  if (timeZone === replacement) return zones;
  const secondary = zones.secondary
    .filter((zone) => zone !== replacement)
    .map((zone) => (zone === timeZone ? replacement : zone));
  if (zones.primary === timeZone) {
    return { primary: replacement, secondary };
  }
  // The primary zone is already shown: the changed column goes
  if (zones.primary === replacement) {
    return {
      ...zones,
      secondary: zones.secondary.filter((zone) => zone !== timeZone),
    };
  }
  return { ...zones, secondary };
}

import { addDays, differenceInCalendarDays, startOfDay } from "date-fns";

import type {
  CalendarEvent,
  CalendarNoticeInput,
  EventHistory,
  EventHistoryAction,
  EventHistoryChange,
  EventHistoryEntry,
  EventPasteTarget,
  VisibleRange,
} from "@/components/calendar-types";
import { getSpokenTitle } from "@/lib/event-utils";

/** Undo steps kept; past it, the oldest are dropped first */
export const EVENT_HISTORY_LIMIT = 100;

/**
 * Two edits to one event less than this many milliseconds apart are one
 * undo step, so a title typed letter by letter is undone at once
 */
export const EVENT_HISTORY_MERGE_MS = 1000;

/** A history with nothing to undo or redo */
export const EMPTY_EVENT_HISTORY: EventHistory = { past: [], future: [] };

/** How each action's announcement starts: "Deleted Team sync" */
const ACTION_ANNOUNCEMENTS: Record<EventHistoryAction | "copy", string> = {
  create: "Created",
  edit: "Changed",
  delete: "Deleted",
  cut: "Cut",
  copy: "Copied",
  duplicate: "Duplicated",
  paste: "Pasted",
};

/** How undo and redo name each action: "Undid deleting Team sync" */
const ACTION_NAMES: Record<EventHistoryAction, string> = {
  create: "creating",
  edit: "editing",
  delete: "deleting",
  cut: "cutting",
  duplicate: "duplicating",
  paste: "pasting",
};

/** First line of the notice each action shows, as Notion Calendar's toasts word it */
const ACTION_NOTICES: Record<"delete" | "cut" | "copy", string> = {
  delete: "Event deleted",
  cut: "Event cut",
  copy: "Event copied to clipboard",
};

/** An edit step's one change with both events, or `null` for any other step */
function getEdit<TEvent extends CalendarEvent>(
  entry: EventHistoryEntry<TEvent>,
): { before: TEvent; after: TEvent; index: number } | null {
  if (entry.action !== "edit" || entry.changes.length !== 1) return null;
  const [change] = entry.changes;
  if (!change.before || !change.after) return null;
  return { before: change.before, after: change.after, index: change.index };
}

/** An event's fields by name, to compare two events field by field */
function getFields(event: CalendarEvent): Record<string, unknown> {
  return event as unknown as Record<string, unknown>;
}

/** Id of the event a change is about */
export function getChangedEventId(change: EventHistoryChange): string {
  return (change.after ?? change.before)?.id ?? "";
}

/**
 * The events after `changes`, in order: an event with a `before` and an
 * `after` is replaced in place, one with only an `after` is inserted at
 * `index` (or last), and one with only a `before` is removed. Other events
 * keep their objects and their order.
 */
export function applyEventChanges<TEvent extends CalendarEvent>(
  events: TEvent[],
  changes: EventHistoryChange<TEvent>[],
): TEvent[] {
  let next = events;
  for (const change of changes) {
    const id = getChangedEventId(change);
    const { before, after } = change;
    if (!after) {
      next = next.filter((event) => event.id !== id);
      continue;
    }
    if (before) {
      next = next.map((event) => (event.id === id ? after : event));
      continue;
    }
    const index = Math.min(Math.max(change.index, 0), next.length);
    next = [...next.slice(0, index), after, ...next.slice(index)];
  }
  return next;
}

/** The changes that undo `changes`: each one reversed, the last first */
export function invertEventChanges<TEvent extends CalendarEvent>(
  changes: EventHistoryChange<TEvent>[],
): EventHistoryChange<TEvent>[] {
  return changes
    .map((change) => ({
      before: change.after,
      after: change.before,
      index: change.index,
    }))
    .reverse();
}

/**
 * Whether `changes` still apply to `events`: each changed event is still
 * the very object the changes start from (`before`), or still absent when
 * they add it. False once the app replaced, removed or re-added one of them
 * from outside, by reloading its events for example, so an undo never
 * overwrites that. Each change must be about a different event.
 */
export function canApplyEventChanges<TEvent extends CalendarEvent>(
  events: TEvent[],
  changes: EventHistoryChange<TEvent>[],
): boolean {
  return changes.every((change) => {
    const id = getChangedEventId(change);
    const current = events.find((event) => event.id === id);
    if (!change.before) return current === undefined;
    return current === change.before;
  });
}

/**
 * Whether two events hold the same values: the same fields, each the same
 * value, or for dates the same time. Shallow: a list or object field must
 * be the same object.
 */
export function isSameEventValue(a: CalendarEvent, b: CalendarEvent): boolean {
  const fieldsA = getFields(a);
  const fieldsB = getFields(b);
  const keys = Object.keys(fieldsA);
  if (keys.length !== Object.keys(fieldsB).length) return false;
  return keys.every((key) => {
    const valueA = fieldsA[key];
    const valueB = fieldsB[key];
    if (valueA instanceof Date && valueB instanceof Date) {
      return valueA.getTime() === valueB.getTime();
    }
    return Object.is(valueA, valueB);
  });
}

/**
 * The history after a new step. The step goes on top, unless it is an edit
 * to the event the top step just edited, less than `EVENT_HISTORY_MERGE_MS`
 * later: then the two are one step, from the event's first value to its
 * last, and that step is dropped when it ends where it began. An edit that
 * changes no value is left out and changes nothing. Otherwise the redo
 * steps are cleared and at most `EVENT_HISTORY_LIMIT` steps are kept.
 */
export function recordEventHistory<TEvent extends CalendarEvent>(
  history: EventHistory<TEvent>,
  entry: EventHistoryEntry<TEvent>,
): EventHistory<TEvent> {
  const edit = getEdit(entry);
  if (edit && isSameEventValue(edit.before, edit.after)) return history;

  const top = history.past[history.past.length - 1];
  const topEdit = top ? getEdit(top) : null;
  if (
    !edit ||
    !top ||
    !topEdit ||
    topEdit.after !== edit.before ||
    entry.time - top.time >= EVENT_HISTORY_MERGE_MS
  ) {
    return {
      past: [...history.past, entry].slice(-EVENT_HISTORY_LIMIT),
      future: [],
    };
  }

  // Quick edits to one event: one step from its first value to its last
  const rest = history.past.slice(0, -1);
  if (isSameEventValue(topEdit.before, edit.after)) {
    return { past: rest, future: [] };
  }
  const merged: EventHistoryEntry<TEvent> = {
    action: "edit",
    changes: [
      { before: topEdit.before, after: edit.after, index: topEdit.index },
    ],
    time: entry.time,
  };
  return { past: [...rest, merged], future: [] };
}

/**
 * Where a paste goes: the spot a view last had the mouse over (`target`)
 * while it is on screen, else today when it is on screen, else the first
 * day on screen (`currentDate`), both at the copied event's own time of day
 */
export function resolvePasteTarget(
  target: EventPasteTarget | null,
  visibleRange: VisibleRange,
  now: Date,
  currentDate: Date,
): EventPasteTarget {
  const isOnScreen = (date: Date) =>
    date >= visibleRange.start && date < visibleRange.end;
  if (target && isOnScreen(target.date)) return target;
  if (isOnScreen(now)) return { date: startOfDay(now), hasTime: false };
  return { date: startOfDay(currentDate), hasTime: false };
}

/**
 * Start and end of a pasted copy of `source`. At a time slot a timed event
 * starts there and keeps its length. On a day, and for an all-day event
 * wherever it goes, the event moves by whole days: it keeps its times of
 * day by the clock, and an all-day event keeps its number of days.
 */
export function getPastedEventTimes(
  source: CalendarEvent,
  target: EventPasteTarget,
): { start: Date; end: Date } {
  if (target.hasTime && !source.isAllDay) {
    const length = source.end.getTime() - source.start.getTime();
    return {
      start: target.date,
      end: new Date(target.date.getTime() + length),
    };
  }
  const days = differenceInCalendarDays(target.date, source.start);
  return { start: addDays(source.start, days), end: addDays(source.end, days) };
}

/** What to announce after an action on an event: "Deleted Team sync" */
export function describeEventAction(
  action: EventHistoryAction | "copy",
  event: CalendarEvent,
): string {
  return `${ACTION_ANNOUNCEMENTS[action]} ${getSpokenTitle(event)}`;
}

/** What to announce after undo or redo: "Undid deleting Team sync" */
export function describeHistoryStep(
  entry: EventHistoryEntry,
  direction: "undo" | "redo",
): string {
  const verb = direction === "undo" ? "Undid" : "Redid";
  const [change] = entry.changes;
  const event = change ? (change.after ?? change.before) : null;
  if (!event) return verb;
  return `${verb} ${ACTION_NAMES[entry.action]} ${getSpokenTitle(event)}`;
}

/**
 * The notice an action shows: "Event deleted" and "Event copied to
 * clipboard" with the event's title (a blank one reads "Untitled event"),
 * "Event cut" without. Duplicate, paste and edits show none.
 */
export function describeEventNotice(
  action: "delete" | "cut" | "copy",
  event: CalendarEvent,
): CalendarNoticeInput {
  const message = ACTION_NOTICES[action];
  if (action === "cut") return { message };
  return { message, title: getSpokenTitle(event) };
}

import { addDays, startOfDay } from "date-fns";

import type {
  DetailedCalendarEvent,
  TimeSpan,
  VisibleRange,
  WorkingHours,
} from "@/components/calendar-types";
import { expandRecurringEvents } from "@/lib/recurrence";

/**
 * Hours the free times everyone shares are looked for in when the provider's
 * `workingHours` is not set: 9 AM to 5 PM, Monday to Friday
 */
export const DEFAULT_WORKING_HOURS: WorkingHours = {
  days: [1, 2, 3, 4, 5],
  startHour: 9,
  endHour: 17,
};

/** Shortest stretch of shared free time worth highlighting, in minutes */
export const MIN_FREE_MINUTES = 30;

/** Whether the event's own calendar owner (`calendarEmail`) declined it */
function isDeclinedByOwner(event: DetailedCalendarEvent): boolean {
  const owner = event.calendarEmail?.toLowerCase();
  if (!owner) return false;
  return (
    event.participants?.some(
      (participant) =>
        participant.email.toLowerCase() === owner &&
        participant.response === "declined",
    ) ?? false
  );
}

/**
 * Whether an event makes the owner of its calendar busy. Events marked
 * `status: "free"`, events the owner declined and birthdays never do.
 * All-day events don't unless marked `status: "busy"`, as Google Calendar
 * shows them as free by default; every other timed event does.
 */
export function isBusyEvent(event: DetailedCalendarEvent): boolean {
  if (event.status === "free") return false;
  if (event.kind === "birthday") return false;
  if (isDeclinedByOwner(event)) return false;
  if (event.isAllDay) return event.status === "busy";
  return true;
}

/**
 * Sorts spans by start and joins the ones that overlap or touch, so the
 * result has no two spans sharing a moment. Empty spans are dropped.
 */
export function mergeTimeSpans(spans: TimeSpan[]): TimeSpan[] {
  const sorted = spans
    .filter((span) => span.end > span.start)
    .sort((a, b) => a.start.getTime() - b.start.getTime());
  const merged: TimeSpan[] = [];
  for (const span of sorted) {
    const last = merged[merged.length - 1];
    if (last && span.start <= last.end) {
      if (span.end > last.end) last.end = new Date(span.end);
      continue;
    }
    merged.push({ start: new Date(span.start), end: new Date(span.end) });
  }
  return merged;
}

/**
 * When one calendar's events keep its owner busy inside `range`: repeating
 * events on each of their dates, clipped to the range and merged. An event
 * counts as busy by `isBusyEvent`. With `timeZone`, the events and the
 * range read on that zone's clock, as the provider hands them to the views,
 * and repeating events are expanded on their instants
 * (`expandRecurringEvents`).
 */
export function getBusyTimes(
  events: DetailedCalendarEvent[],
  range: VisibleRange,
  timeZone?: string,
): TimeSpan[] {
  const spans: TimeSpan[] = [];
  for (const event of expandRecurringEvents(events, range, timeZone)) {
    if (!isBusyEvent(event)) continue;
    if (event.end <= range.start || event.start >= range.end) continue;
    spans.push({
      start: event.start < range.start ? range.start : event.start,
      end: event.end > range.end ? range.end : event.end,
    });
  }
  return mergeTimeSpans(spans);
}

/**
 * The working hours of each given day, on the clock `days` read on (the
 * viewer's, or the calendar's for the provider's days): a day outside
 * `workingHours.days` has none. `endHour` 24 ends at the next midnight.
 */
export function getWorkingTimes(
  days: Date[],
  workingHours: WorkingHours = DEFAULT_WORKING_HOURS,
): TimeSpan[] {
  const { startHour, endHour } = workingHours;
  if (endHour <= startHour) return [];
  return days
    .filter((day) =>
      workingHours.days.some((weekday) => weekday === day.getDay()),
    )
    .map((day) => {
      const midnight = startOfDay(day);
      return {
        start: new Date(
          midnight.getFullYear(),
          midnight.getMonth(),
          midnight.getDate(),
          startHour,
        ),
        end: new Date(
          midnight.getFullYear(),
          midnight.getMonth(),
          midnight.getDate(),
          endHour,
        ),
      };
    });
}

/** Options of `getSharedFreeTime` */
interface SharedFreeTimeOptions {
  /** Days and hours to look in. Defaults to `DEFAULT_WORKING_HOURS` */
  workingHours?: WorkingHours;
  /** Shortest free stretch kept, in minutes. Defaults to `MIN_FREE_MINUTES` */
  minMinutes?: number;
  /**
   * The calendar's zone, when `calendars` and `days` read on its clock (the
   * provider's mapped events, with its `timeZone` set). The working hours
   * then read on that clock too.
   */
  timeZone?: string;
}

/**
 * The times on `days` when nobody is busy: inside working hours, outside
 * every calendar's busy times (`getBusyTimes`), and at least `minMinutes`
 * long. Each calendar is one person's events; pass yours and those of the
 * people you're meeting with. Times are instants, so events written in other
 * time zones block the moments they cover; the working hours are the
 * viewer's, or `timeZone`'s with it.
 */
export function getSharedFreeTime(
  calendars: DetailedCalendarEvent[][],
  days: Date[],
  {
    workingHours = DEFAULT_WORKING_HOURS,
    minMinutes = MIN_FREE_MINUTES,
    timeZone,
  }: SharedFreeTimeOptions = {},
): TimeSpan[] {
  const working = getWorkingTimes(days, workingHours);
  if (working.length === 0) return [];
  const range: VisibleRange = {
    start: startOfDay(days.reduce((a, b) => (a < b ? a : b))),
    end: addDays(startOfDay(days.reduce((a, b) => (a > b ? a : b))), 1),
  };
  const busy = mergeTimeSpans(
    calendars.flatMap((events) => getBusyTimes(events, range, timeZone)),
  );
  const minMs = minMinutes * 60_000;

  const free: TimeSpan[] = [];
  for (const span of working) {
    let cursor = span.start;
    for (const block of busy) {
      if (block.end <= cursor) continue;
      if (block.start >= span.end) break;
      if (block.start > cursor) free.push({ start: cursor, end: block.start });
      cursor = block.end > cursor ? block.end : cursor;
      if (cursor >= span.end) break;
    }
    if (cursor < span.end) free.push({ start: cursor, end: span.end });
  }
  return free.filter(
    (slot) => slot.end.getTime() - slot.start.getTime() >= minMs,
  );
}

import type {
  CalendarPerson,
  EventColor,
  EventContact,
  EventParticipant,
} from "@/components/calendar-types";

/**
 * Colors given to people whose contact sets none, by their place in
 * `contacts`: every event color but gray, so their events stand apart from
 * gray "Busy" blocks
 */
export const PERSON_COLORS: readonly EventColor[] = [
  "blue",
  "orange",
  "purple",
  "green",
  "red",
  "yellow",
];

/** Most people a "Meet with..." list shows at once */
export const MAX_PEOPLE_SUGGESTIONS = 6;

/**
 * A typed address that can be added without a contact, as strict as the
 * details' participants field: a plain local part, then a domain of
 * letters, digits and hyphens with a 2+ letter TLD
 */
export const EMAIL_PATTERN =
  /^[A-Za-z0-9._%+'-]+@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\.)+[A-Za-z]{2,}$/;

/** Whether two emails name the same person (emails ignore case) */
export function isSameEmail(a: string, b: string): boolean {
  return a.trim().toLowerCase() === b.trim().toLowerCase();
}

/** The name a person is shown with: their name, else their email */
export function getPersonName(contact: EventContact): string {
  return contact.name?.trim() || contact.email;
}

/** One letter for a person's avatar: their name's, else their email's */
export function getPersonInitial(contact: EventContact): string {
  return getPersonName(contact).charAt(0).toUpperCase();
}

/** The contact with this email, or a bare `{ email }` when none has it */
export function findContact(
  contacts: readonly EventContact[],
  email: string,
): EventContact {
  return (
    contacts.find((contact) => isSameEmail(contact.email, email)) ?? {
      email,
    }
  );
}

/**
 * A person as the calendar draws them: their contact, with their own color
 * or the one their place in `contacts` picks from `PERSON_COLORS` (people
 * not in `contacts` take the next ones after them)
 */
export function getCalendarPerson(
  contacts: readonly EventContact[],
  email: string,
): CalendarPerson {
  const contact = findContact(contacts, email);
  if (contact.color) return { ...contact, color: contact.color };
  const index = contacts.findIndex((c) => isSameEmail(c.email, email));
  const place = index === -1 ? contacts.length : index;
  return { ...contact, color: PERSON_COLORS[place % PERSON_COLORS.length] };
}

/**
 * Adds an email to a list, keeping its order. The list comes back as it was
 * when the email is in it already (in any case).
 */
export function addEmail(emails: readonly string[], email: string): string[] {
  const trimmed = email.trim();
  if (!trimmed || emails.some((e) => isSameEmail(e, trimmed))) {
    return [...emails];
  }
  return [...emails, trimmed];
}

/** Takes an email out of a list (in any case) */
export function removeEmail(
  emails: readonly string[],
  email: string,
): string[] {
  return emails.filter((e) => !isSameEmail(e, email));
}

/** Whether a contact matches typed text: a word of its name starts with it, or its email contains it */
export function matchesPerson(contact: EventContact, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  if (contact.email.toLowerCase().includes(q)) return true;
  const name = contact.name?.toLowerCase() ?? "";
  return name.startsWith(q) || name.split(/\s+/).some((w) => w.startsWith(q));
}

/**
 * The people a "Meet with..." or "Show teammate calendar..." list offers
 * for typed text, leaving out `exclude` (the people already added). With
 * nothing typed: the recent contacts first, then the others. While typing:
 * the matches, in their order in `contacts`.
 */
export function suggestPeople(
  contacts: readonly EventContact[],
  query: string,
  exclude: readonly string[] = [],
  limit = MAX_PEOPLE_SUGGESTIONS,
): EventContact[] {
  const available = contacts.filter(
    (contact) => !exclude.some((email) => isSameEmail(email, contact.email)),
  );
  if (!query.trim()) {
    return [
      ...available.filter((contact) => contact.recent),
      ...available.filter((contact) => !contact.recent),
    ].slice(0, limit);
  }
  return available
    .filter((contact) => matchesPerson(contact, query))
    .slice(0, limit);
}

/**
 * The typed text as someone to add when it's an email address that no
 * contact has and nobody added yet, else `null`
 */
export function getTypedPerson(
  contacts: readonly EventContact[],
  typed: string,
  exclude: readonly string[] = [],
): EventContact | null {
  const email = typed.trim();
  if (!EMAIL_PATTERN.test(email)) return null;
  if (contacts.some((contact) => isSameEmail(contact.email, email))) {
    return null;
  }
  if (exclude.some((added) => isSameEmail(added, email))) return null;
  return { email };
}

/**
 * The participants of an event created while meeting with people: the
 * event's own, then everyone met with who isn't invited yet, waiting for an
 * answer. When anyone is added, the calendar's account (`owner`) organizes
 * unless the event already has an organizer, as the details' participants
 * field does it.
 */
export function addMeetingParticipants(
  participants: readonly EventParticipant[],
  people: readonly EventContact[],
  owner?: string,
): EventParticipant[] {
  const invited = people
    .filter(
      (person) =>
        !participants.some((p) => isSameEmail(p.email, person.email)) &&
        !(owner && isSameEmail(person.email, owner)),
    )
    .map(
      (person): EventParticipant => ({
        email: person.email,
        ...(person.name ? { name: person.name } : {}),
        response: "needs-action",
      }),
    );
  if (invited.length === 0) return [...participants];
  const hasOrganizer = participants.some((p) => p.organizer);
  const ownerListed =
    owner !== undefined &&
    participants.some((p) => isSameEmail(p.email, owner));
  const organizer: EventParticipant[] =
    owner && !hasOrganizer && !ownerListed
      ? [{ email: owner, organizer: true, response: "accepted" }]
      : [];
  return [...organizer, ...participants, ...invited];
}

